const deal = $input.first().json.result || {};
const catId = Number(deal.CATEGORY_ID);
const createdById = Number(deal.CREATED_BY_ID || deal.UF_CRM_TI_REQUESTER);
const allowedRequesters = [32598];

// Guard conditions
if (catId !== 160) {
  return [{ json: { status: 'IGNORED', reason: 'NOT_CATEGORY_160', deal_id: deal.ID, cat_id: catId } }];
}

if (!allowedRequesters.includes(createdById)) {
  return [{ json: { status: 'IGNORED', reason: 'REQUESTER_NOT_ALLOWED', deal_id: deal.ID, requester: createdById } }];
}

return [{ json: {
  deal_id: Number(deal.ID),
  requester_id: createdById,
  title: deal.TITLE || '',
  comments: deal.COMMENTS || '',
  category_uf: deal.UF_CRM_1763388156 || null,
  subcategory_uf: deal.UF_CRM_1763388469429 || null,
  store_uf: deal.UF_CRM_1689593052602 || null,
  deal_data: deal
} }];

// Knowledge Extractor & Theme Detection Engine
const inputData = $input.first().json;

// Canonical Theme Detection
let themeId = 'GENERICO';
const catMap = {
  '880': 'COMPUTADOR', '882': 'IMPRESSORA', '878': 'ERP_MICROWORK',
  '908': 'ATPV_RENAVE', '874': 'BITRIX24', '918': 'DESATIVAR_ACESSO',
  '920': 'CAMERA', '876': 'COMPRA_EQUIPAMENTO', '916': 'ACESSO_SENHA'
};

if (inputData.category_uf && catMap[String(inputData.category_uf)]) {
  themeId = catMap[String(inputData.category_uf)];
}

return [{
  json: {
    deal_id: inputData.deal_id,
    requester_id: inputData.requester_id,
    theme_id: themeId,
    initial_question: 'START_TRIAGE',
    status: 'START_CONVERSATION'
  }
}];
